     PermissionRequest {
         #[serde(default)]
         permission_id: Option<String>,
         #[serde(default)]
         session_id: Option<String>,
         tool: String,
         #[serde(default)]
         reason: String,
         #[serde(default)]
         args: Value,
     },
     PermissionDecision {
         #[serde(default)]
         permission_id: Option<String>,
         #[serde(default)]
         session_id: Option<String>,
     },
     #[serde(other)]
     Other,
 }

