 /// Wrap-forward: `(idx + 1) % len`. Returns 0 for empty lists.
 fn next_index(idx: usize, len: usize) -> usize {
     if len == 0 {
         0
     } else {
         (idx + 1) % len
     }
 }

 /// Wrap-backward: `(idx + len - 1) % len`. Returns 0 for empty lists.
 fn prev_index(idx: usize, len: usize) -> usize {
     if len == 0 {
         0
     } else {
         (idx + len - 1) % len
     }
 }

