 #[derive(Clone)]
 struct ScoredCommand {
     command: Command,
     score: f64,
 }

 impl PartialEq for ScoredCommand {
     fn eq(&self, other: &Self) -> bool {
         self.command.id == other.command.id && self.score == other.score
     }
 }

