   472	#[derive(Debug, PartialEq)]
   473	struct SampledPlot {
   474	    paths: Vec<String>,
   475	    y_min: f64,
   476	    y_max: f64,
   477	}
   478	
   479	fn sample_plot(
   480	    config: &PlotConfig,
   481	    parameters: &BTreeMap<String, f64>,
   482	) -> Result<SampledPlot, String> {
   483	    let mut values = parameters.clone();
   484	    let mut sampled = vec![Vec::with_capacity(config.x.samples); config.series.len()];
   485	    let mut y_min = f64::INFINITY;
   486	    let mut y_max = f64::NEG_INFINITY;
   487	
   488	    for sample in 0..config.x.samples {
   489	        let progress = sample as f64 / (config.x.samples - 1) as f64;
   490	        let x = config.x.min + progress * (config.x.max - config.x.min);
   491	        values.insert(config.x.id.clone(), x);
   492	        for (index, series) in config.series.iter().enumerate() {
   493	            let y = series
   494	                .expression
   495	                .evaluate(&values)
   496	                .map_err(|error| format!("{} could not be evaluated: {error}", series.label))?;
   497	            y_min = y_min.min(y);
   498	            y_max = y_max.max(y);
   499	            sampled[index].push((progress, y));
   500	        }
   501	    }
   502	
   503	    if !y_min.is_finite() || !y_max.is_finite() {
   504	        return Err("the plot did not produce finite values".into());
   505	    }
   506	    if (y_max - y_min).abs() < f64::EPSILON {
   507	        let padding = y_max.abs().max(1.0) * 0.05;
   508	        let padded_min = y_min - padding;
   509	        let padded_max = y_max + padding;
   510	        if !padded_min.is_finite() || !padded_max.is_finite() {
   511	            return Err("the plot range is too large to normalize".into());
   512	        }
   513	        y_min = padded_min;
   514	        y_max = padded_max;
   515	    }
   516	    let span = y_max - y_min;
   517	    if !span.is_finite() || span <= 0.0 {
   518	        return Err("the plot range is too large to normalize".into());
   519	    }
   520	    let paths = sampled
   521	        .into_iter()
   522	        .map(|points| {
   523	            points
   524	                .into_iter()
   525	                .enumerate()
   526	                .map(|(index, (x, y))| {
   527	                    let command = if index == 0 { 'M' } else { 'L' };
   528	                    let plot_x = x * 120.0;
   529	                    let plot_y = 60.0 - (y - y_min) / span * 60.0;
   530	                    if !plot_x.is_finite() || !plot_y.is_finite() {
   531	                        return Err("the plot produced invalid normalized geometry".to_string());
   532	                    }
   533	                    Ok(format!("{command}{plot_x:.3},{plot_y:.3}"))
   534	                })
   535	                .collect::<Result<Vec<_>, _>>()
   536	                .map(|segments| segments.join(" "))
   537	        })
   538	        .collect::<Result<Vec<_>, _>>()?;
   539	    Ok(SampledPlot {
   540	        paths,
   541	        y_min,
   542	        y_max,
   543	    })
   544	}
