   546	fn update_parameter(
   547	    values: RwSignal<BTreeMap<String, f64>>,
   548	    parameter: &Parameter,
   549	    raw: &str,
   550	) -> Option<f64> {
   551	    let value = raw.parse::<f64>().ok()?;
   552	    if !value.is_finite() {
   553	        return None;
   554	    }
   555	    let value = value.clamp(parameter.min, parameter.max);
   556	    values.update(|current| {
   557	        current.insert(parameter.id.clone(), value);
   558	    });
   559	    Some(value)
   560	}
   561	
   562	fn format_value(value: f64, precision: usize) -> String {
   563	    let rendered = format!("{value:.precision$}");
   564	    let Some((whole, fraction)) = rendered.split_once('.') else {
   565	        return rendered;
   566	    };
   567	    let fraction = fraction.trim_end_matches('0');
   568	    if fraction.is_empty() {
   569	        whole.to_string()
   570	    } else {
   571	        format!("{whole}.{fraction}")
   572	    }
   573	}
