   464	fn finite_number(value: &Value, key: &str) -> Result<f64, String> {
   465	    value
   466	        .get(key)
   467	        .and_then(Value::as_f64)
   468	        .filter(|number| number.is_finite())
   469	        .ok_or_else(|| format!("{key} must be a finite number"))
   470	}
